'use strict'
// Accessor exports: the enumerable one is read once when the facade
// binds (its side effect prints at import); the NON-enumerable one is
// never read — Bun enumerates own keys, and reading it would run the
// getter (ioredis warns from its `Promise` getter this way).
exports.plain = 1
Object.defineProperty(exports, 'Lazy', {
  get() { console.log('lazy getter ran'); return 2 },
  set(_lib) {},
})
Object.defineProperty(exports, 'Shown', {
  enumerable: true,
  get() { console.log('shown getter ran'); return 3 },
})
